NAME = 'VulgSistine: Vulgata Sistina'
BOOK = 'I Peter'

CHAPTERS = {
    1: {
        1: 'Petrus Apostolus Iesu Christi, electis advenis dispersionis Ponti, Galatiae, Cappadociae, Asiae, et Bithyniae,',
        2: 'secundum praescientiam Dei Patris, in sanctificationem Spiritus, in obedientiam, et aspersionem sanguinis Iesu Christi: Gratia vobis, et pax multiplicetur.',
        3: 'Benedictus Deus et Pater Domini nostri Iesu Christi, qui secundum misericordiam suam magnam regeneravit nos in spem vivam, per resurrectionem Iesu Christi ex mortuis,',
        4: 'in hereditatem incorruptibilem, et incontaminatam, et immarcescibilem, conservatam in caelis in vobis,',
        5: 'qui in virtute Dei custodimini per fidem in salutem, paratam revelari in tempore novissimo.',
        6: 'In quo exultabis, modicum nunc si oportet contristari in variis tentationibus:',
        7: 'ut probatio vestrae fidei multo pretiosior auro (quod per ignem probatur) inveniatur in laudem, et gloriam, et honorem in revelatione Iesu Christi:',
        8: 'quem cum non videritis, diligitis: in quem nunc quoque non videntes creditis: credentes autem exultabitis laetitia inenarrabili, et glorificata:',
        9: 'reportantes finem fidei vestrae, salutem animarum vestrarum.',
        10: 'De qua salute exquisierunt, atque scrutati sunt prophetae, qui de futura in vobis gratia prophetaverunt:',
        11: 'scrutantes in quod, vel quale tempus significaret in eis Spiritus Christi: praenuncians eas quae in Christo sunt passiones, et posteriores glorias:',
        12: 'quibus revelatum est quia non sibimetipsis, vobis autem ministrabant ea, quae nunc nunciata sunt vobis per eos, qui evangelizaverunt vobis, Spiritu sancto misso de caelo, in quem desiderant Angeli prospicere.',
        13: 'Propter quod succincti lumbos mentis vestrae, sobrii, perfecti, sperate in eam, quae offertur vobis, gratiam, in revelationem Iesu Christi:',
        14: 'quasi filii obedientiae, non configurati prioribus ignorantiae vestrae desideriis:',
        15: 'sed secundum eum, qui vocavit vos, Sanctum: ut et ipsi in omni conversatione sancti sitis:',
        16: 'quoniam scriptum est: Sancti eritis, quoniam ego Sanctus sum.',
        17: 'Et si patrem invocatis eum, qui sine acceptione personarum iudicat secundum uniuscuiusque opus, in timore incolatus vestri tempore conversamini.',
        18: 'Scientes quod non corruptibilibus auro, vel argento redempti estis de vana vestra conversatione paternae traditionis:',
        19: 'sed pretioso sanguine quasi agni immaculati Christi, et incontaminati:',
        20: 'praecogniti quidem ante mundi constitutionem, manifestati autem novissimis temporibus propter vos,',
        21: 'qui per ipsum fideles estis in Deo, qui suscitavit eum a mortuis, et dedit ei gloriam, ut fides vestra, et spes esset in Deo:',
        22: 'Animas vestras castificantes in obedientia charitatis, in fraternitatis amore, simplici ex corde invicem diligite attentius:',
        23: 'renati non ex semine corruptibili, sed incorruptibili per verbum Dei vivi, et permanentis in aeternum:',
        24: 'quia omnis caro ut foenum: et omnis gloria eius tamquam flos foeni: exaruit foenum, et flos eius decidit.',
        25: 'Verbum autem Domini manet in aeternum. hoc est autem verbum, quod evangelizatum est in vobis.',
    },
    2: {
        1: 'Deponentes igitur omnem malitiam, et omnem dolum, et simulationes, et invidias, et omnes detractiones,',
        2: 'sicut modo geniti infantes, rationabiles sine dolo lac concupiscite: ut in eo crescatis in salutem:',
        3: 'si tamen gustastis quoniam dulcis est Dominus.',
        4: 'Ad quem accedentes lapidem vivum, ab hominibus quidem reprobatum, a Deo autem electum, et honorificatum:',
        5: 'et ipsi tamquam lapides vivi superaedificamini, domos spirituales, sacerdotium sanctum, offerre spirituales hostias, acceptabiles Deo per Iesum Christum:',
        6: 'Propter quod continet Scriptura: Ecce pono in Sion lapidem summum angularem probatum, electum, pretiosum: et qui crediderit in eum, non confundetur.',
        7: 'Vobis igitur honor credentibus: non credentibus autem lapis, quem reprobaverunt aedificantes, hic factus est in caput anguli:',
        8: 'et lapis offensionis, et petra scandali his, qui offendunt verbo, nec credunt in quo et positi sunt.',
        9: 'Vos autem genus electum, regale sacerdotium, gens sancta, populus acquisitionis: ut virtutes annuncietis eius, qui de tenebris vos vocavit in admirabile lumen suum.',
        10: 'Qui aliquando non populus Dei, nunc autem populus Dei: qui non consecuti misericordiam, nunc autem misericordiam consecuti.',
        11: 'Charissimi, obsecro vos tamquam advenas et peregrinos abstinere vos a carnalibus desideriis, quae militant adversus animam,',
        12: 'conversationem vestram inter Gentes habentes bonam: ut in eo, quod detrectant de vobis tamquam de malefactoribus, ex bonis operibus vos considerantes, glorificent Deum in die visitationis.',
        13: 'Subiecti igitur estote omni humanae creaturae propter Deum: sive regi quasi praecellenti:',
        14: 'sive ducibus tamquam ab eo missis ad vindictam malefactorum, laudem vero bonorum:',
        15: 'quia sic est voluntas Dei, ut benefacientes obmutescere faciatis imprudentium hominum ignorantiam:',
        16: 'quasi liberi, et non quasi velamen habentes malitiae libertatem, sed sicut servi Dei.',
        17: 'Omnes honorate: fraternitatem diligite: Deum timete: Regem honorificate.',
        18: 'Servi subditi estote in omni timore dominis, non tantum bonis et modestis, sed etiam dyscolis.',
        19: 'Haec est enim gratia, si propter Dei conscientiam sustinet quis tristitias, patiens iniuste.',
        20: 'Quae enim est gratia, si peccantes, et colaphizati suffertis? sed si bene facientes patienter sustinetis: haec est gratia apud Deum.',
        21: 'In hoc enim vocati estis: quia et Christus passus est pro nobis, vobis relinquens exemplum ut sequamini vestigia eius.',
        22: 'qui peccatum non fecit, nec inventus est dolus in ore eius:',
        23: 'qui cum malediceretur, non maledicebat: cum pateretur, non comminabatur: tradebat autem iudicanti se iniuste:',
        24: 'qui peccata nostra ipse pertulit in corpore suo super lignum: ut peccatis mortui, iustitiae vivamus: cuius livore sanati estis.',
        25: 'Eratis enim sicut oves errantes, sed conversi estis nunc ad pastorem, et episcopum animarum vestrarum.',
    },
    3: {
        1: 'Similiter et mulieres subditae sint viris suis: ut et si qui non credunt verbo, per mulierem conversationem sine verbo lucrifiant,',
        2: 'considerantes in timore castam conversationem vestram.',
        3: 'Quarum non sit extrinsecus capillatura, aut circumdatio auri, aut indumenti vestimentorumve cultus:',
        4: 'sed qui absconditus est cordis homo, in incorruptibilitate quieti, et modesti spiritus, qui est in conspectu Dei locuples.',
        5: 'Sic enim aliquando et sanctae mulieres, sperantes in Deo, ornabant se, subiectae propriis viris.',
        6: 'Sicut Sara obediebat Abrahae, dominum eum vocans: cuius estis filiae benefacientes, et non pertimentes ullam perturbationem.',
        7: 'Viri similiter cohabitantes secundum scientiam, quasi infirmiori vasculo muliebri impartientes honorem, tamquam et coheredibus gratiae vitae: ut non impediantur orationes vestrae.',
        8: 'In fide autem omnes unanimes, compatientes, fraternitatis amatores, misericordes, modesti, humiles:',
        9: 'non reddentes malum pro malo, nec maledictum pro maledicto, sed econtrario benedicentes: quia in hoc vocati estis, ut benedictionem hereditate possideatis.',
        10: 'Qui enim vult vitam diligere, et dies videre bonos, coerceat linguam suam a malo, et labia eius ne loquantur dolum.',
        11: 'Declinet a malo, et faciat bonum: inquirat pacem, et sequatur eam:',
        12: 'Quia oculi Domini super iustos, et aures eius in preces eorum: Vultus autem Domini super facientes mala.',
        13: 'Et quis est qui vobis noceat, si boni aemulatores fueritis?',
        14: 'Sed et si quid patimini propter iustitiam, beati. Timorem autem eorum ne timueritis, et non conturbemini.',
        15: 'Dominum autem Christum sanctificate in cordibus vestris, parati semper ad satisfactionem omni poscenti vos rationem de ea, quae in vobis est, fide et spe.',
        16: 'sed cum modestia, et timore, conscientiam habentes bonam: ut in eo, quod detrahunt de vobis, confundantur, qui calumniantur vestram bonam in Christo conversationem.',
        17: 'Melius est enim ut benefacientes (si voluntas Dei velit) pati, quam malefacientes.',
        18: 'quia et Christus semel pro peccatis nostris mortuus est, iustus pro iniustis, ut nos offerret Deo, mortificatos quidem carne, vivificatos autem spiritu.',
        19: 'In quo et his, qui in carcere erant, spiritibus veniens praedicavit:',
        20: 'qui increduli fuerant aliquando, quando expectabant Dei patientiam in diebus Noe, cum fabricaretur arca: in qua pauci, id est octo animae salvae factae sunt per aquam.',
        21: 'Quod et vos nunc similis formae salvos fecit baptisma: non carnis depositio sordium, sed conscientiae bonae interrogatio in Deum per resurrectionem Iesu Christi,',
        22: 'qui est in dextera Dei, deglutiens mortem ut vitae aeternae heredes efficeremur: profectus in caelum subiectis sibi angelis, et potestatibus, et virtutibus.',
    },
    4: {
        1: 'Christo igitur passo in carne, et vos eadem cogitatione armamini: quia qui passus est in carne, desiit a peccatis:',
        2: 'Ut iam non desideriis hominum, sed voluntati Dei, quod reliquum est in carne vivat temporis.',
        3: 'Sufficit enim praeteritum tempus ad voluntatem Gentium consummandam his, qui ambulaverunt in luxuriis, desideriis, vinolentiis, comessationibus, potationibus ebrietatibus, et illicitis idolorum cultibus.',
        4: 'In quo admirantur non concurrentibus vobis in eamdem luxuriae confusionem, blasphemantes.',
        5: 'Qui reddent rationem ei, qui paratus est iudicare vivos et mortuos.',
        6: 'Propter hoc enim et mortuis evangelizatum est: ut iudicentur quidem secundum homines in carne, vivant autem secundum Deum in Spiritu.',
        7: 'Omnium autem finis appropinquavit. Estote itaque prudentes, et vigilate in orationibus.',
        8: 'Ante omnia autem, mutuam in vobismetipsis charitatem continuam habentes: quia charitas operit multitudinem peccatorum.',
        9: 'Hospitales invicem sine murmuratione:',
        10: 'Unusquisque, sicut accepit gratiam, in alterutrum illam administrantes, sicut boni dispensatores multiformis gratiae Dei.',
        11: 'Si quis loquitur, quasi sermones Dei: si quis ministrat, tamquam ex virtute, quam administrat Deus: ut in omnibus honorificetur Deus per Iesum Christum: cui est gloria, et imperium in saecula saeculorum: Amen.',
        12: 'Charissimi, nolite peregrinari in fervore, qui ad tentationem vobis fit, quasi novi aliquid vobis contingat:',
        13: 'sed communicantes Christi passionibus gaudete, ut et in revelatione gloriae eius gaudeatis exultantes.',
        14: 'Si exprobramini in nomine Christi, beati eritis: quoniam quod est honoris, gloriae, et virtutis Dei, et qui est eius Spiritus, super vos requiescit.',
        15: 'Nemo autem vestrum patiatur ut homicida, aut fur, aut maledicus, aut alienorum appetitor.',
        16: 'Si autem ut Christianus, non erubescat: glorificet autem Deum in isto nomine.',
        17: 'quoniam tempus est ut incipiat iudicium a domo Dei. Si autem primum a nobis: quis finis eorum, qui non credunt Dei Evangelio?',
        18: 'Et si iustus quidem vix salvabitur, impius, et peccator ubi parebunt?',
        19: 'Itaque et hi, qui patiuntur secundum voluntatem Dei, fideli Creatori commendent animas suas in benefactis.',
    },
    5: {
        1: 'Seniores ergo, qui in vobis sunt, obsecro, consenior et testis Christi passionum: qui et eius, quae in futuro revelanda est, gloriae communicator:',
        2: 'pascite qui in vobis est gregem Dei, providentes non coacte, sed spontanee secundum Deum: neque turpis lucri gratia, sed voluntarie:',
        3: 'neque ut dominantes in cleris, sed forma facti gregis ex animo.',
        4: 'Et cum apparuerit princeps pastorum, percipietis immarcescibilem gloriae coronam.',
        5: 'Similiter adolescentes subditi estote senioribus. Omnes autem invicem humilitatem insinuate, quia Deus superbis resistit, humilibus autem dat gratiam.',
        6: 'Humiliamini igitur sub potenti manu Dei, ut vos exaltet in tempore visitationis:',
        7: 'omnem solicitudinem vestram proiicientes in eum, quoniam ipsi cura est de vobis.',
        8: 'Sobrii estote, et vigilate: quia adversarius vester diabolus tamquam leo rugiens circuit, quaerens quem devoret:',
        9: 'Cui resistite fortes in fide: scientes eamdem passionem ei, quae in mundo est, vestrae fraternitati fieri.',
        10: 'Deus autem omnis gratiae, qui vocavit nos in aeternam suam gloriam in Christo Iesu, modicum passos ipse perficiet, confirmabit, solidabitque.',
        11: 'Ipsi gloria, et imperium in saecula saeculorum: Amen.',
        12: 'Per Silvanum fidelem fratrem vobis, ut arbitror, breviter scripsi: obsecrans et contestans, hanc esse veram gratiam Dei, in qua statis.',
        13: 'Salutat vos Ecclesia, quae est in Babylone collecta, et Marcus filius meus.',
        14: 'Salutate invicem in osculo sancto: Gratia vobis omnibus, qui estis in Christo Iesu. Amen.',
    },
}
